/// A registered ontology, as cortext's ontology registry stores it: one
/// governed object per dropped ontology file, homed in the `.models` system
/// directory beside `ModelManifest` (the same governed-object recipe), with an
/// ACL the owner controls and the platform's own revision history.
///
/// The object is a *reference*, like `ModelManifest`: the authored YAML is a
/// Drive file named here by id, content revision and sha256. The dropped file
/// is the *bronze* ontology, kept where it landed as provenance; registration
/// writes a normalised *silver* rendering (explicit name/description/layer on
/// every class, `parents`/`links` always lists, the derived `parents_flat` and
/// `links_flat` arrays the relation DSL iterates) and `source` names that
/// silver file. The fields a reader queries on (class ids, names, layers,
/// parents) are projected once per source revision into the `ontologies`
/// registry (registry.fbs), so nothing on a read path opens the YAML.
///
/// Every class the file declares is `<namespace>:<UpperCamelCase>`, where the
/// prefix is the owner's namespace (their directory username, resolved once
/// and recorded on this object as `namespace` + `authored_by`); `ul` is the
/// platform tier, owned by the service identity.
#[derive(Default, PartialEq, Debug, Clone, Hash, Eq, Serialize, Deserialize)]
pub struct OntologyDeclaration {
    /// The registering principal (oid).
    pub authored_by: Option<String>,
    /// The Drive file object the user dropped (the bronze ontology), as
    /// provenance.
    pub bronze: Option<ObjectId>,
    /// That file's content revision at registration.
    pub bronze_cid: Option<ContentId>,
    /// The owner's namespace: the CURIE prefix of every class declared here.
    pub namespace: String,
    /// The file's `ontology:` id, stable within the namespace; with the
    /// namespace it derives the object id, so a re-drop revises the same object.
    pub ontology_id: String,
    /// `"<namespace>/<ontology_id>"` — the registry key. A derived field the
    /// registrant writes so the spec's single-field key can name it.
    pub ontology_key: String,
    /// The Drive file object holding the silver (normalised) rendering.
    pub source: ObjectId,
    /// That file's content revision at registration.
    pub source_cid: Option<ContentId>,
    /// sha256 (hex) of the silver bytes; the projector verifies it.
    pub source_sha256: String,
}

